examples.template:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space4) {
    VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
        Text({{reply}})
        MonarchAiArtifactCard({{artifact.title}}, kind: {{artifact.kind|case}}, version: {{artifact.version}}, isActive: true) {}
    }
    MonarchAiArtifactCanvas(
        MonarchAiCanvasArtifact(
            id: {{artifact.id}},
            kind: {{artifact.kind|case}},
            title: {{artifact.title}},
            version: {{artifact.version}},
            content: versions[1].content ?? ""
        ),
        versions: versions,
        saveTitle: {{saveLabel}},
        labels: MonarchAiArtifactCanvasLabels(share: "Download"),
        onVersionChange: { _ in },
        onSave: { _ in },
        onClose: {}
    )
}
.environment(\.locale, Locale(identifier: {{locale}}))
.environment(\.timeZone, TimeZone(identifier: {{timeZone}}) ?? .gmt)

examples.code:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space4) {
    VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
        Text("Here is the summary you asked for.")
        MonarchAiArtifactCard("Q3 summary", kind: .document, version: 2, isActive: true) {}
    }
    MonarchAiArtifactCanvas(
        MonarchAiCanvasArtifact(
            id: "q3",
            kind: .document,
            title: "Q3 summary",
            version: 2,
            content: versions[1].content ?? ""
        ),
        versions: versions,
        saveTitle: "Save to library",
        labels: MonarchAiArtifactCanvasLabels(share: "Download"),
        onVersionChange: { _ in },
        onSave: { _ in },
        onClose: {}
    )
}
.environment(\.locale, Locale(identifier: "en-GB"))
.environment(\.timeZone, TimeZone(identifier: "Europe/London") ?? .gmt)

